"""Independent certificate verifier for controller results."""
import json, random
from fractions import Fraction
from bisect import bisect_left, bisect_right


def build_arcs(case, ratio, thresholds, values):
    S = len(case['slots']); F = len(case['flows']); G = len(case['groups'])
    J = len(case['windows'])
    B, I = case['bucket']
    times = [s[0] for s in case['slots']]
    W = 1 + J * times[-1]
    def Z(f): return 2 + 3 * S + J + f
    def H(g): return 2 + 3 * S + J + F + g
    arcs = []  # (u,v,lower,cap,cost)
    for s in range(S):
        intake = I if s == 0 else case['slots'][s][2]
        arcs.append((0, 2 + 3 * s, 0, intake, 0))
        arcs.append((2 + 3 * s, 3 + 3 * s, 0, B, 0))
        if s + 1 < S:
            arcs.append((3 + 3 * s, 2 + 3 * (s + 1), 0, B, 0))
        arcs.append((3 + 3 * s, 4 + 3 * s, 0, case['slots'][s][1], 0))
    for s in range(S):
        for j in range(J):
            w = case['windows'][j]
            if not (w[5] < thresholds[j]):
                continue
            if not (w[1] <= times[s] <= w[2]):
                continue
            arcs.append((4 + 3 * s, 2 + 3 * S + j, 0, 1,
                         (times[s] - w[1]) - values[j] * W))
    for j in range(J):
        arcs.append((2 + 3 * S + j, Z(case['windows'][j][0]), 0, 1, 0))
    for f in range(F):
        gp = case['flows'][f][2]
        head = H(gp) if gp >= 0 else 1
        low = -((-ratio * case['flows'][f][0]) // 1)
        low = (ratio.numerator * case['flows'][f][0] + ratio.denominator - 1) // ratio.denominator
        arcs.append((Z(f), head, low, case['flows'][f][1], 0))
    for g in range(G):
        p = case['groups'][g][0]
        head = H(p) if p >= 0 else 1
        arcs.append((H(g), head, 0, case['groups'][g][1], 0))
    arcs.append((1, 0, 0, J, 0))
    return arcs


def verify(case, result, thresholds, values):
    errs = []
    ratio = Fraction(result['ratio'][0], result['ratio'][1])
    arcs = build_arcs(case, ratio, thresholds, values)
    flow = result['flow']
    if len(flow) != len(arcs):
        errs.append('flow length %d != %d' % (len(flow), len(arcs)))
        return errs
    K = 2 + 3 * len(case['slots']) + len(case['windows']) + len(case['flows']) + len(case['groups'])
    bal = [0] * K
    for idx, (u, v, l, h, c) in enumerate(arcs):
        x = flow[idx]
        if type(x) is not int:
            errs.append('arc %d not int' % idx); continue
        if x < l or x > h:
            errs.append('arc %d flow %d outside [%d,%d]' % (idx, x, l, h))
        bal[u] -= x
        bal[v] += x
        pot = result['potential']
        if x < h and c + pot[u] - pot[v] < 0:
            errs.append('arc %d forward potential violation' % idx)
        if x > l and -c + pot[v] - pot[u] < 0:
            errs.append('arc %d backward potential violation' % idx)
    for v in range(K):
        if bal[v] != 0:
            errs.append('node %d imbalance %d' % (v, bal[v]))
    # assignment consistency
    S = len(case['slots'])
    J = len(case['windows'])
    assign = result['assignment']
    arcidx = {}
    i = 4 * S - 1
    for s in range(S):
        for j in range(J):
            w = case['windows'][j]
            if w[5] < thresholds[j] and w[1] <= times[s] <= w[2]:
                arcidx[(s, j)] = i
                i += 1
    seen = set()
    for j in range(J):
        s = assign[j]
        if s < 0:
            continue
        if (s, j) not in arcidx:
            errs.append('window %d assigned to ineligible slot %d' % (j, s)); continue
        if flow[arcidx[(s, j)]] != 1:
            errs.append('window %d slot %d arc flow != 1' % (j, s))
        if j in seen:
            errs.append('window %d twice' % j)
        seen.add(j)
    for (s, j), idx in arcidx.items():
        if flow[idx] == 1 and assign[j] != s:
            errs.append('arc (%d,%d) flow 1 but assignment %d' % (s, j, assign[j]))
        if flow[idx] not in (0, 1):
            errs.append('arc (%d,%d) flow not unit' % (s, j))
    # utility / age
    times_l = times
    util = sum(values[j] for j in range(J) if assign[j] >= 0)
    age = sum(times_l[assign[j]] - case['windows'][j][1]
              for j in range(J) if assign[j] >= 0)
    if util != result['utility']:
        errs.append('utility %d != %d' % (result['utility'], util))
    if age != result['age']:
        errs.append('age %d != %d' % (result['age'], age))
    # coverage
    nf = [0] * len(case['flows'])
    for j in range(J):
        if assign[j] >= 0:
            nf[case['windows'][j][0]] += 1
    r = min([Fraction(1)] + [Fraction(nf[f], case['flows'][f][0])
                             for f in range(len(case['flows']))])
    if r != ratio:
        errs.append('ratio %s != coverage %s' % (result['ratio'], r))
    if ratio.denominator > 64 or ratio.numerator > ratio.denominator:
        errs.append('ratio malformed')
    # cut
    if ratio < 1:
        rset = set()
        for f in range(len(case['flows'])):
            t = case['flows'][f][0]
            for k in range(t + 1):
                rset.add(Fraction(k, t))
        nxt = min(x for x in rset if x > ratio)
        arcs2 = build_arcs(case, nxt, thresholds, values)
        cut = result['cut']
        if not cut:
            errs.append('missing cut')
        else:
            X = set(cut)
            if len(X) != len(cut):
                errs.append('cut duplicates')
            if any(x < 0 or x >= K for x in cut):
                errs.append('cut node out of range')
            lin = sum(a[2] for a in arcs2 if a[0] not in X and a[1] in X)
            cout = sum(a[3] for a in arcs2 if a[0] in X and a[1] not in X)
            if lin <= cout:
                errs.append('cut not blocking: lin=%d cout=%d' % (lin, cout))
    else:
        if result['cut'] is not None:
            errs.append('cut must be null when ratio is 1')
    for p in result['potential']:
        if type(p) is not int or abs(p) > 10 ** 60:
            errs.append('bad potential value')
    return errs


def objective_key(case, assign, thresholds, values):
    nf = [0] * len(case['flows'])
    J = len(case['windows'])
    for j in range(J):
        if assign[j] >= 0:
            nf[case['windows'][j][0]] += 1
    r = min([Fraction(1)] + [Fraction(nf[f], case['flows'][f][0])
                             for f in range(len(case['flows']))])
    util = sum(values[j] for j in range(J) if assign[j] >= 0)
    times = [s[0] for s in case['slots']]
    age = sum(times[assign[j]] - case['windows'][j][1]
              for j in range(J) if assign[j] >= 0)
    return (-r, -util, age)


def brute(case, thresholds, values):
    S = len(case['slots']); J = len(case['windows'])
    times = [s[0] for s in case['slots']]
    best = None
    bestassign = None
    opts = []
    for j in range(J):
        w = case['windows'][j]
        o = [-1]
        if w[5] < thresholds[j]:
            for s in range(S):
                if w[1] <= times[s] <= w[2]:
                    o.append(s)
        opts.append(o)
    # iterative product
    total = 1
    for o in opts:
        total *= len(o)
    for mask in range(total):
        m = mask
        assign = []
        ok = True
        for j in range(J):
            k = m % len(opts[j]); m //= len(opts[j])
            assign.append(opts[j][k])
        # ceilings
        nf = [0] * len(case['flows'])
        for j in range(J):
            if assign[j] >= 0:
                f = case['windows'][j][0]
                nf[f] += 1
                if nf[f] > case['flows'][f][1]:
                    ok = False; break
        if not ok:
            continue
        # group ceilings (all ancestors)
        load = [0] * len(case['groups'])
        for f in range(len(case['flows'])):
            g = case['flows'][f][2]
            while g >= 0:
                load[g] += nf[f]
                g = case['groups'][g][0]
        for g in range(len(case['groups'])):
            if load[g] > case['groups'][g][1]:
                ok = False; break
        if not ok:
            continue
        # tokens / slot capacity
        per_slot = [0] * S
        for j in range(J):
            if assign[j] >= 0:
                per_slot[assign[j]] += 1
        for s in range(S):
            if per_slot[s] > case['slots'][s][1]:
                ok = False; break
        if not ok:
            continue
        inv = case['bucket'][1]
        Bc = case['bucket'][0]
        inv = min(Bc, inv)
        for s in range(S):
            if s > 0:
                inv = min(Bc, inv + case['slots'][s][2])
            if per_slot[s] > inv:
                ok = False; break
            inv -= per_slot[s]
        if not ok:
            continue
        key = objective_key(case, assign, thresholds, values)
        if best is None or key < best:
            best = key
            bestassign = list(assign)
    return best, bestassign
